// Kabar's Android glue (share target + ML Kit OCR), compiled as a Gradle library module.
//
// You never build this directly: `dx` finds it through the
// `#[manganis::ffi("../../android")]` marker in crates/app/src/platform/android.rs,
// copies this folder into its generated Gradle project as `:plugins:plugin`, adds it as a
// dependency of the app and lets the Android manifest merger pull in our activity.
// The root project generated by dx supplies the AGP and Kotlin plugin versions, so the
// plugins below carry no versions on purpose.

plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
}

android {
    namespace = "app.kabar.bridge"
    compileSdk = 34

    defaultConfig {
        minSdk = 28
        // R8 must keep the classes Rust looks up by name over JNI.
        consumerProguardFiles("consumer-rules.pro")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = "17"
    }

    sourceSets {
        getByName("main") {
            java.srcDirs("src/main/kotlin")
        }
    }
}

dependencies {
    // ML Kit Text Recognition v2, Latin script, with the model bundled in the APK:
    // free, on-device, no Google Play services download. Terms: see ATTRIBUTION.md.
    implementation("com.google.mlkit:text-recognition:16.0.1")
}
